async function save(){if(previewActive()){previewContext.testState=appState;previewContext.updatedAt=now();pendingAudit=[];setSyncStatus('Sistema di prova aggiornato · dati reali protetti');toast('Prova aggiornata: puoi cambiare ruolo e continuare il collaudo');return}saving=true;try{const stamp=now(),audit=[...pendingAudit];const {error}=await db.from('shared_state').update({payload:appState,updated_at:stamp}).eq('id',1);if(error)throw error;lastRemoteUpdated=stamp;if(audit.length){const {error:auditError}=await db.from('activity_log').upsert(audit.map(e=>({id:e.id,line:e.line,event_text:e.text,actor_name:e.actor,event_kind:e.kind,created_at:e.at,user_id:session?.user?.id})));if(auditError)throw auditError;pendingAudit=pendingAudit.filter(e=>!audit.some(a=>a.id===e.id));sendPushEvents(audit)}setSyncStatus('Sincronizzato in tempo reale')}catch(e){setSyncStatus('Da sincronizzare',true);toast(e.message,true)}finally{saving=false}}
