function previewBottlePhoto(input){const f=input.files[0],p=$('#photoPreview');if(!f||!p)return;const url=URL.createObjectURL(f);p.onload=()=>URL.revokeObjectURL(url);p.onerror=()=>{URL.revokeObjectURL(url);p.hidden=true;toast('Anteprima non disponibile: prova a scegliere la foto dalla galleria',true)};p.src=url;p.hidden=false}
function setBottleLineChecks(code=''){const assigned=appState.bottleLines[code]||[selected];document.querySelectorAll('[name="mapBottleLine"]').forEach(input=>input.checked=assigned.includes(input.value));const all=$('#mapAllLines');if(all)all.checked=names.every(name=>assigned.includes(name))}
function toggleAllBottleLines(checked){document.querySelectorAll('[name="mapBottleLine"]').forEach(input=>input.checked=checked)}
function fillBottleDetails(code){const b=code.trim(),known=appState.bottles.includes(b);setBottleLineChecks(known?b:'');if(!known)return;$('#mapName').value=appState.bottleNames[b]||'';const p=$('#photoPreview');if(appState.bottleImages[b]){p.src=appState.bottleImages[b];p.hidden=false}else{p.removeAttribute('src');p.hidden=true}}
function previewSelectedBottle(code){const b=code.trim(),p=$('#selectedBottlePreview');if(!p)return;if(!appState.bottles.includes(b)){p.innerHTML='';return}p.innerHTML=`<div class="bottle-preview-row">${appState.bottleImages[b]?`<img src="${appState.bottleImages[b]}" alt="Foto flacone">`:'<span class="no-photo mini">Foto</span>'}<span><b>${esc(appState.bottleNames[b]||'Flacone')}</b><br>${esc(b)}</span></div>`}
async function saveBottleDetails(){try{if(!isCT())return toast('Operazione non autorizzata',true);const b=$('#mapBottle').value.trim(),n=$('#mapName').value.trim(),f=$('#mapPhoto').files[0],lineValues=[...document.querySelectorAll('[name="mapBottleLine"]:checked')].map(input=>input.value);if(!b||!n)return toast('Inserisci nome e codice',true);if(!lineValues.length)return toast('Scegli almeno una linea',true);toast(f?'Caricamento foto in corso…':'Salvataggio in corso…');appState.bottleNames[b]=n;if(f)appState.bottleImages[b]=await uploadBottlePhoto(f,b);if(!appState.bottles.includes(b))appState.bottles.push(b);appState.bottleLines[b]=lineValues;Object.values(appState.lines).filter(l=>l.bottle===b).forEach(l=>{l.bottleName=n;l.bottleImage=appState.bottleImages[b]||''});await save();const dialog=$('#bottleEditorDialog');if(dialog)dialog.close();render();toast(`Flacone salvato per ${lineValues.length===names.length?'tutte le linee':lineValues.join(', ')}`)}catch(e){toast(e.message||'Foto non salvata',true)}}
function loadBottleCard(code){const b=decodeURIComponent(code);if(!isCT())return toast('Operazione non autorizzata',true);showBottleEditDialog(b)}
async function selectBottleFromArchive(code){if(!isCT())return toast('Operazione non autorizzata',true);const b=decodeURIComponent(code),targetLine=$('#archiveTargetLine')?.value||selected;if(targetLine==='all'){appState.bottleLines[b]=[...names];await save();render();showBottleArchiveDialog();toast(`Codice ${b} disponibile su tutte le linee`);return}pendingArchiveBottle=b;pendingArchiveLine=targetLine;selected=targetLine;$('#bottleEditorDialog')?.close();render();showArchiveCodeQuantity(b,targetLine)}
async function deleteBottle(code){const b=decodeURIComponent(code);if(!isCT())return toast('Solo il CT può eliminare i codici',true);const activeLines=Object.values(appState.lines).filter(l=>String(l.bottle).trim()===b&&l.stage!=='idle'),active=activeLines.map(l=>l.name),name=appState.bottleNames[b]||'Flacone',photo=appState.bottleImages[b]||'';const warning=active.length?`\n\nÈ in uso sulle linee ${active.join(', ')}: le linee continueranno normalmente, ma il codice sparirà dall’archivio.`:'';if(!confirm(`Eliminare il codice ${b} dall’archivio?${warning}`))return;activeLines.forEach(l=>{l.bottleName=l.bottleName||name;l.bottleImage=l.bottleImage||photo});if(!active.length&&!previewActive()){const safe=b.replace(/[^a-zA-Z0-9_-]/g,'_');await db.storage.from('bottle-photos').remove([`${safe}.jpg`])}appState.bottles=appState.bottles.filter(x=>x!==b);if(CODIFICA_CATALOG.some(item=>item.code===b)){appState.catalogDeleted=Array.isArray(appState.catalogDeleted)?appState.catalogDeleted:[];if(!appState.catalogDeleted.includes(b))appState.catalogDeleted.push(b)}delete appState.bottleColors[b];delete appState.bottleNames[b];delete appState.bottleImages[b];delete appState.bottleLines[b];await save();render();showBottleArchiveDialog();toast(`Codice ${b} ${previewActive()?'rimosso dalla simulazione':'eliminato dall’archivio'}`)}
function bottleArchive(){if(!isCT())return'';const codes=[...appState.bottles].sort((a,b)=>a.localeCompare(b,'it'));return `<div class="archive-details archive-search-only"><div class="archive-dialog-heading"><strong>Cerca nell’archivio flaconi</strong><small>Scrivi il codice oppure una parte del nome del flacone.</small></div><label class="field archive-search">Codice o nome flacone<input type="search" id="bottleArchiveSearch" name="bottleArchiveQuery" placeholder="Es. P01558 oppure Elseve" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" oninput="filterBottleArchive(this.value)"></label><small id="bottleArchiveResultCount" class="archive-result-count">Scrivi almeno 2 caratteri per cercare</small><label class="field archive-target">Carica il codice sulla linea<select id="archiveTargetLine"><option value="${selected}">Linea ${selected}</option>${names.filter(name=>name!==selected).map(name=>`<option value="${name}">Linea ${name}</option>`).join('')}<option value="all">Tutte le linee</option></select></label><div class="archive-grid archive-grid-compact">${codes.map(b=>{const bottleName=appState.bottleNames[b]||'Flacone';return `<div class="archive-card archive-card-compact" hidden data-bottle-search="${esc(`${b} ${bottleName}`.toLowerCase())}"><b class="archive-code">${esc(b)}</b><span class="archive-name">${esc(bottleName)}</span><div class="archive-actions"><button class="primary" onclick="selectBottleFromArchive('${encodeURIComponent(b)}')">Scegli</button><button onclick="loadBottleCard('${encodeURIComponent(b)}')">Modifica</button><button class="danger" onclick="deleteBottle('${encodeURIComponent(b)}')">Elimina</button></div></div>`}).join('')}</div></div>`}
function filterBottleArchive(value){const query=value.trim().toLowerCase(),cards=[...document.querySelectorAll('.archive-card[data-bottle-search]')],count=$('#bottleArchiveResultCount');if(query.length<2){cards.forEach(card=>card.hidden=true);if(count)count.textContent='Scrivi almeno 2 caratteri per cercare';return}const matches=cards.filter(card=>card.dataset.bottleSearch.includes(query));cards.forEach(card=>card.hidden=true);matches.slice(0,12).forEach(card=>card.hidden=false);if(count)count.textContent=matches.length?matches.length>12?`${matches.length} risultati · affinare la ricerca`:`${matches.length} ${matches.length===1?'risultato':'risultati'}`:'Nessun flacone trovato'}
function bottleCreateForm(title='Crea nuovo codice'){return `<strong class="bottle-editor-title">${esc(title)}</strong><div class="grid bottle-editor-grid"><label class="field">Nome flacone<input id="mapName" placeholder="Es. Shampoo nero"></label><label class="field">Codice flacone<input id="mapBottle" list="bottles" placeholder="Inserisci il codice"></label><label class="field">Foto flacone · galleria o fotocamera<input id="mapPhoto" type="file" accept="image/*,.heic,.heif" onchange="previewBottlePhoto(this)"><small>Su iPhone scegli “Libreria foto” per cercare nella galleria.</small></label></div><fieldset class="bottle-line-picker"><legend>Linee sulle quali usare questo flacone</legend><label class="all-lines"><input id="mapAllLines" type="checkbox" onchange="toggleAllBottleLines(this.checked)"> Seleziona tutte le linee</label><div>${names.map(name=>`<label><input type="checkbox" name="mapBottleLine" value="${name}" ${name===selected?'checked':''}> ${name}</label>`).join('')}</div></fieldset><img id="photoPreview" class="photo-preview" hidden alt="Anteprima foto scelta"><div class="actions"><button class="primary" onclick="saveBottleDetails()">Salva flacone e linee</button></div>`}
function bottleEditorShell(content){const old=$('#bottleEditorDialog');if(old)old.remove();const dialog=document.createElement('dialog');dialog.id='bottleEditorDialog';dialog.className='line-quick-dialog bottle-editor-dialog';dialog.innerHTML=`<button class="line-quick-close" aria-label="Chiudi">×</button>${content}`;document.body.appendChild(dialog);dialog.querySelector('.line-quick-close').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();return dialog}
function showBottleEditorMenu(){if(!isCT())return toast('Solo Amministratore, CT, Vice CT e Processista possono gestire i codici',true);const dialog=bottleEditorShell(`<strong>Gestione codici flacone</strong><p>Cosa vuoi fare?</p><div class="bottle-editor-actions"><button class="primary" id="createBottleChoice"><span>＋</span>Crea nuovo codice</button><button id="archiveBottleChoice"><span>▦</span>Apri archivio flaconi</button><button id="editBottleChoice">Modifica codice esistente</button></div>`);dialog.querySelector('#createBottleChoice').onclick=showBottleCreateDialog;dialog.querySelector('#archiveBottleChoice').onclick=showBottleArchiveDialog;dialog.querySelector('#editBottleChoice').onclick=showBottleEditPicker}
function showBottleArchiveDialog(){if(!isCT())return toast('Operazione non autorizzata',true);const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Archivio flaconi</strong>${bottleArchive()}`);dialog.classList.add('bottle-archive-dialog');setTimeout(()=>dialog.querySelector('#bottleArchiveSearch')?.focus(),80)}
