function bottleEditPickerResults(){return [...appState.bottles].sort((a,b)=>a.localeCompare(b,'it')).map(code=>{const name=appState.bottleNames[code]||'Flacone',photo=appState.bottleImages[code]||'';return `<button type="button" class="bottle-edit-result" hidden data-bottle-edit-search="${esc(`${code} ${name}`.toLowerCase())}" data-edit-bottle="${encodeURIComponent(code)}">${photo?`<img src="${photo}" alt="Foto ${esc(name)}">`:'<span class="no-photo mini">Foto</span>'}<span><b>${esc(code)}</b><small>${esc(name)}</small></span><strong>Modifica →</strong></button>`}).join('')}
function filterBottleEditPicker(value){const query=value.trim().toLowerCase(),results=[...document.querySelectorAll('[data-bottle-edit-search]')],message=$('#bottleEditResultCount');results.forEach(result=>result.hidden=true);if(query.length<2){if(message)message.textContent='Scrivi almeno 2 caratteri per cercare';return}const matches=results.filter(result=>result.dataset.bottleEditSearch.includes(query));matches.slice(0,8).forEach(result=>result.hidden=false);if(message)message.textContent=matches.length?matches.length>8?`${matches.length} risultati · continua a scrivere per restringere`:`${matches.length} ${matches.length===1?'risultato':'risultati'}`:'Nessun codice trovato'}
function showBottleEditPicker(){if(!isCT())return toast('Operazione non autorizzata',true);const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Modifica codice esistente</strong><p>Inizia a scrivere il codice o il nome del flacone: vedrai subito l’anteprima dei risultati.</p><label class="field bottle-edit-search">Codice o nome flacone<input id="editBottleCode" type="search" inputmode="text" placeholder="Es. P015442400 oppure Elseve" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false"></label><small id="bottleEditResultCount" class="archive-result-count">Scrivi almeno 2 caratteri per cercare</small><div class="bottle-edit-results">${bottleEditPickerResults()}</div>`);const input=dialog.querySelector('#editBottleCode');input.oninput=()=>filterBottleEditPicker(input.value);dialog.querySelectorAll('[data-edit-bottle]').forEach(button=>button.onclick=()=>{const code=decodeURIComponent(button.dataset.editBottle);dialog.close();showBottleEditDialog(code)});setTimeout(()=>input.focus(),100)}
function showBottleEditDialog(code,options={}){if(!isCT())return toast('Operazione non autorizzata',true);const dialog=bottleEditorShell(bottleCreateForm(`Modifica codice ${code}`));$('#mapBottle').value=code;$('#mapBottle').readOnly=true;$('#mapName').value=appState.bottleNames[code]||'';setBottleLineChecks(code);const p=$('#photoPreview');if(appState.bottleImages[code]){p.src=appState.bottleImages[code];p.hidden=false}const actions=dialog.querySelector('.actions');if(actions){actions.insertAdjacentHTML('beforeend','<button type="button" class="danger delete-bottle-edit" id="deleteBottleFromEdit">Elimina questo codice</button>');dialog.querySelector('#deleteBottleFromEdit').onclick=()=>{dialog.close();deleteBottle(encodeURIComponent(code))}}if(options.openPhotoPicker){const photoInput=dialog.querySelector('#mapPhoto');photoInput?.click()}else setTimeout(()=>dialog.querySelector('#mapName')?.focus(),100)}
function showBottlePhotoDialog(code){if(!isCT())return toast('Solo Amministratore, CT, Vice CT e Processista possono aggiungere fotografie',true);if(previewActive())return toast('Le fotografie reali non si modificano nel sistema di prova',true);const bottle=decodeURIComponent(code);if(!appState.bottles.includes(bottle))return toast('Codice non trovato nell’archivio',true);showBottleEditDialog(bottle,{openPhotoPicker:true})}
function bindLinePhotoButtons(){document.querySelectorAll('[data-add-bottle-photo]').forEach(button=>{button.onpointerdown=event=>event.stopPropagation();button.ontouchstart=event=>event.stopPropagation();button.onclick=event=>{event.preventDefault();event.stopPropagation();showBottlePhotoDialog(button.dataset.addBottlePhoto)}})}
function productionLineSelector(l){const available=Object.values(appState.lines).filter(line=>isCT()||canOperateLine(line));return `<label class="field production-line-choice">Scegli linea<select id="productionLineSelect">${available.map(line=>`<option value="${line.name}" ${line.name===l.name?'selected':''}>Linea ${line.name}${line.bottle?` · ${esc(appState.bottleNames[line.bottle]||line.bottleName||line.bottle)}`:''}</option>`).join('')}</select></label>`}
function productionBox(l){const selector=productionLineSelector(l),progress=l.productionTarget?`<div class="production-day-chip">Giornata produttiva · ${esc(productionDayLabel(l.productionDayKey||currentProductionDay()))}</div><h3>${Number(l.productionDone).toLocaleString('it-IT')} / ${Number(l.productionTarget).toLocaleString('it-IT')} ${unitLabel(l)}</h3><small class="production-last-update">${esc(productionUpdatedLabel(l))}</small><p>Assorbiti oggi <strong>${Number(l.productionDone).toLocaleString('it-IT')} ${unitLabel(l)}</strong> · Da assorbire ancora <strong>${productionRemaining(l).toLocaleString('it-IT')} ${unitLabel(l)}</strong></p>`:'<p>Quantità da assorbire non ancora impostata per la linea scelta.</p>',update=l.productionTarget&&isCT()?`<label class="field">Totale assorbito dall’inizio della giornata alle 06:00<input id="productionDone" type="number" min="0" max="${l.productionTarget}" value="${l.productionDone}"></label><small class="muted">Ogni turno sostituisce il valore precedente. Non inserire soltanto la quantità del turno.</small><div class="actions"><button class="primary" id="updateProduction">Aggiorna totale giornaliero</button></div>`:'',plan=isCT()?`<details class="production-plan"><summary>CT · modifica quantità da assorbire</summary><div class="actions"><select id="planUnit"><option value="pieces" ${l.productionUnit!=='ot'?'selected':''}>Pezzi</option><option value="ot" ${l.productionUnit==='ot'?'selected':''}>O.T.</option></select><input id="planTarget" type="number" min="1" value="${l.productionTarget||''}" placeholder="Quantità da assorbire"><button id="setProductionPlan">Salva quantità</button></div></details>`:'';return `<div class="notice production-overview" id="sectionProductionProgress"><strong>Avanzamento produzione</strong>${selector}${progress}${update}${plan}</div>`}
function queueBottleSearchResults(){return [...appState.bottles].sort((a,b)=>a.localeCompare(b,'it')).map(code=>{const name=appState.bottleNames[code]||'Flacone',photo=appState.bottleImages[code]||'';return `<button type="button" class="bottle-edit-result queue-bottle-result" hidden data-queue-bottle-search="${esc(`${code} ${name}`.toLowerCase())}" data-queue-bottle-choice="${encodeURIComponent(code)}" onclick="chooseQueueBottle('${encodeURIComponent(code)}')">${photo?`<img src="${photo}" alt="Foto ${esc(name)}">`:'<span class="no-photo mini">Foto</span>'}<span><b>${esc(code)}</b><small>${esc(name)}</small></span><strong>Scegli →</strong></button>`}).join('')}
function showQueueBottleSelection(code){const preview=$('#queueBottleSelected');if(!preview)return;if(!appState.bottles.includes(code)){preview.innerHTML='';preview.hidden=true;return}const name=appState.bottleNames[code]||'Flacone',photo=appState.bottleImages[code]||'';preview.innerHTML=`${photo?`<img src="${photo}" alt="Foto ${esc(name)}">`:'<span class="no-photo mini">Foto</span>'}<span><small>Codice selezionato</small><b>${esc(code)}</b><strong>${esc(name)}</strong></span>`;preview.hidden=false}
function filterQueueBottleSearch(value){const query=value.trim().toLowerCase(),results=[...document.querySelectorAll('[data-queue-bottle-search]')],message=$('#queueBottleResultCount'),exact=appState.bottles.find(code=>code.toLowerCase()===query);results.forEach(result=>result.hidden=true);showQueueBottleSelection(exact||'');if(query.length<2){if(message)message.textContent='Scrivi almeno 2 caratteri per cercare';return}const matches=results.filter(result=>result.dataset.queueBottleSearch.includes(query));matches.slice(0,8).forEach(result=>result.hidden=false);if(message)message.textContent=exact?`Codice ${exact} selezionato`:matches.length?matches.length>8?`${matches.length} risultati · continua a scrivere per restringere`:`${matches.length} ${matches.length===1?'risultato':'risultati'}`:'Nessun codice trovato'}
function chooseQueueBottle(code){const bottle=decodeURIComponent(code),input=$('#queueBottle');if(!input||!appState.bottles.includes(bottle))return;input.value=bottle;document.querySelectorAll('[data-queue-bottle-search]').forEach(result=>result.hidden=true);const message=$('#queueBottleResultCount');if(message)message.textContent=`Codice ${bottle} selezionato`;showQueueBottleSelection(bottle);$('#queueTarget')?.focus()}
