function renderCtBottomNav(){const nav=$('#ctBottomNav'),allowed=canUseCtBottomNav();if(!nav)return;document.body.classList.toggle('ct-bottom-nav-visible',allowed);nav.hidden=!allowed;nav.setAttribute('aria-hidden',String(!allowed));if(!allowed){nav.innerHTML='';return}nav.innerHTML=ctBottomNavItems.map(item=>`<button type="button" data-ct-nav="${item.key}" aria-label="${item.label}" ${ctBottomNavActive===item.key?'class="selected" aria-current="page"':''}>${item.icon}<span>${item.label}</span></button>`).join('');nav.querySelectorAll('[data-ct-nav]').forEach(button=>button.onclick=()=>openCtBottomSection(button.dataset.ctNav))}
