async function loadTeamChatContext(){if(previewActive()){teamChatAvailable=false;return}try{const {data,error}=await db.rpc('available_chat_teams');if(error)throw error;teamChatAvailable=true;teamChatTeams=(data||[]).map(item=>({code:item.team_code,color:safeTeamColor(item.team_color)}));if(!canSeeAllTeamChats()){const code=profile?.team_code||'';teamChatTeams=code?[{code,color:safeTeamColor(profile?.team_color)}]:[];activeChatTeam=code}else if(!activeChatTeam||!teamChatTeams.some(item=>item.code===activeChatTeam))activeChatTeam=teamChatTeams[0]?.code||'';await refreshTeamChatUnread()}catch(e){teamChatAvailable=false;teamChatTeams=[];teamChatUnread=0}}
function startTeamChatNotifications(){if(teamChatNotifyChannel){db.removeChannel(teamChatNotifyChannel);teamChatNotifyChannel=null}if(!teamChatAvailable||previewActive())return;teamChatNotifyChannel=db.channel(`team-chat-notify-${session?.user?.id||Date.now()}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'team_chat_messages'},payload=>{const message=payload.new,allowed=canSeeAllTeamChats()||message.team_code===profile?.team_code;if(!allowed||message.user_id===session?.user?.id)return;teamChatUnread++;updateTeamChatBell();if(notificationAllowed()&&document.hidden)new Notification(`Chat squadra ${message.team_code}`,{body:`${message.author_name}: ${message.body}`,icon:'./icon.svg',tag:`team-chat-${message.team_code}`})}).subscribe()}
