const DEVICE_DEMO_KEY='reparto-live-device-handover-demo-v1';
const deviceConditionLabels={in_order:'In ordine',existing_damage:'Danno già presente',new_damage:'Nuovo danno',unusable:'Non utilizzabile'};
const devicePartLabels={screen:'Schermo / vetro',body:'Cover / scocca',camera:'Fotocamera',buttons:'Tasti',charge:'Presa di ricarica',battery:'Batteria',dirty:'Sporco',other:'Altro'};
function loadDeviceDemo(){try{return{active:null,history:[],reports:[],...JSON.parse(localStorage.getItem(DEVICE_DEMO_KEY)||'{}')}}catch{return{active:null,history:[],reports:[]}}}
function saveDeviceDemo(data){localStorage.setItem(DEVICE_DEMO_KEY,JSON.stringify(data))}
function nextShiftBoundary(date=new Date()){const boundary=new Date(date);const hour=date.getHours();if(hour<6)boundary.setHours(6,0,0,0);else if(hour<14)boundary.setHours(14,0,0,0);else if(hour<22)boundary.setHours(22,0,0,0);else{boundary.setDate(boundary.getDate()+1);boundary.setHours(6,0,0,0)}return boundary}
function updateShiftCountdown(){const boundary=nextShiftBoundary(),remaining=Math.max(0,boundary-Date.now()),hours=Math.floor(remaining/3600000),minutes=Math.floor(remaining%3600000/60000),seconds=Math.floor(remaining%60000/1000);document.querySelectorAll('[data-shift-countdown]').forEach(element=>element.textContent=`${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`)}
function addDeviceReport(data,condition,part,note,phase){if(condition==='in_order')return;data.reports.unshift({id:crypto.randomUUID(),device:defaultDeviceLabel(),reportedBy:actor(),reportedAt:now(),condition,part,description:note||devicePartLabels[part]||deviceConditionLabels[condition],phase,status:'new',assignedTo:''});data.reports=data.reports.slice(0,100)}
function showDeviceHandoverDialog(mode='take'){const data=loadDeviceDemo(),isReturn=mode==='return',dialog=bottleEditorShell(`<strong class="bottle-editor-title">${isReturn?'Riconsegna dispositivo':'Presa dispositivo'}</strong><p class="device-dialog-intro">${isReturn?'Conferma velocemente lo stato finale prima del cambio turno.':'Controlla il dispositivo e conferma la presa in carico.'}</p><section class="device-dialog-id"><small>Dispositivo aziendale</small><strong>${esc(defaultDeviceLabel())}</strong><span>${esc(actor())}</span></section><fieldset class="device-condition-picker"><legend>Stato ${isReturn?'finale':'iniziale'}</legend>${Object.entries(deviceConditionLabels).map(([value,label])=>`<label class="device-condition-option"><input type="radio" name="deviceCondition" value="${value}" ${value==='in_order'?'checked':''}><span>${value==='in_order'?'✓':value==='unusable'?'!':'⚠'}</span><b>${label}</b></label>`).join('')}</fieldset><section id="deviceDamageDetails" class="device-damage-details" hidden><label class="field">Parte interessata<select id="deviceDamagePart">${Object.entries(devicePartLabels).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label class="field" id="deviceDamageNoteField" hidden>Descrizione breve<input id="deviceDamageNote" maxlength="120" placeholder="Scrivi quale danno"></label><p>La segnalazione sarà inviata automaticamente alla checklist.</p></section><button class="primary device-dialog-confirm" id="confirmDeviceHandover">${isReturn?'Conferma riconsegna':'Conferma presa dispositivo'}</button>`);const conditionInputs=[...dialog.querySelectorAll('[name="deviceCondition"]')],details=dialog.querySelector('#deviceDamageDetails'),part=dialog.querySelector('#deviceDamagePart'),noteField=dialog.querySelector('#deviceDamageNoteField');const refresh=()=>{const condition=conditionInputs.find(input=>input.checked)?.value||'in_order';details.hidden=condition==='in_order';noteField.hidden=part.value!=='other'};conditionInputs.forEach(input=>input.onchange=refresh);part.onchange=refresh;refresh();dialog.querySelector('#confirmDeviceHandover').onclick=()=>{const condition=conditionInputs.find(input=>input.checked)?.value||'in_order',partValue=condition==='in_order'?'':part.value,note=dialog.querySelector('#deviceDamageNote').value.trim();if(condition!=='in_order'&&partValue==='other'&&!note)return toast('Descrivi brevemente il danno',true);const record={id:crypto.randomUUID(),deviceId:currentDeviceId(),device:defaultDeviceLabel(),user:actor(),condition,part:partValue,note,at:now()};if(isReturn){if(!data.active)return toast('Nessuna consegna attiva',true);data.history.unshift({...data.active,returnedAt:record.at,returnedBy:record.user,finalCondition:condition,finalPart:partValue,finalNote:note});data.history=data.history.slice(0,100);addDeviceReport(data,condition,partValue,note,'Riconsegna');data.active=null}else{data.active=record;addDeviceReport(data,condition,partValue,note,'Presa in carico')}saveDeviceDemo(data);dialog.close();renderChecklistHub();toast(isReturn?'Dispositivo riconsegnato':'Dispositivo preso in carico')}}
function showShiftChangeDemo(){const data=loadDeviceDemo(),dialog=bottleEditorShell(`<strong class="bottle-editor-title">Cambio turno protetto</strong><div class="shift-demo-flow"><div><span>1</span><strong>Salvataggio automatico</strong><small>Nessun dato di produzione viene perso.</small></div><div><span>2</span><strong>Controllo dispositivo</strong><small>${data.active?'È richiesta la riconsegna e lo stato finale.':'Nessuna consegna attiva su questo dispositivo.'}</small></div><div><span>3</span><strong>Uscita obbligatoria</strong><small>Alle 06:00, 14:00 e 22:00 la sessione viene chiusa.</small></div><div><span>4</span><strong>Nuovo login</strong><small>La persona del turno successivo entra con il proprio account.</small></div></div><p class="device-demo-note">Questa è una simulazione: nella demo non verrai realmente scollegato.</p><button class="primary device-dialog-confirm" id="closeShiftDemo">Ho capito</button>`);dialog.querySelector('#closeShiftDemo').onclick=()=>dialog.close()}
function updateDeviceReport(reportId){const data=loadDeviceDemo(),report=data.reports.find(item=>item.id===reportId);if(!report)return;if(report.status==='new'){report.status='in_progress';report.assignedTo=actor()}else if(report.status==='in_progress')report.status='resolved';else if(report.status==='resolved')report.status='closed';saveDeviceDemo(data);renderChecklistHub()}
function lineReturnBagVisual(type,pieces=0){return `<div class="return-bag-visual is-${type}"><span class="return-bag-frame"><i></i></span><strong>${type==='medium'?'MEDIUM BAG':'BIG BAG'}</strong><b>${Number(pieces||0).toLocaleString('it-IT')} pezzi</b></div>`}
function renderLineReturnsWidget(){const widget=$('#lineReturnsWidget'),tools=$('#productionQuickTools');if(!widget)return;const pending=(appState.lineReturns||[]).filter(item=>item.status!=='associated'),visible=currentArea==='production'&&(!canUseCtBottomNav()||ctBottomNavActive==='home');if(tools)tools.hidden=!visible;widget.hidden=!visible;if(!visible){widget.innerHTML='';return}widget.innerHTML=`<button type="button" id="registerLineReturn" class="return-home-card"><span class="return-widget-icon">↩${pending.length?`<b>${pending.length}</b>`:''}</span><span><strong>Nuovo reso</strong><small>${pending.length?`${pending.length} ${pending.length===1?'reso da associare':'resi da associare'}`:'Big Bag o Medium Bag'}</small></span><em>Apri →</em></button>`;$('#registerLineReturn').onclick=showLineReturnDialog}
function showLineReturnDialog(){let scanner=null;const pending=(appState.lineReturns||[]).filter(item=>item.status!=='associated').length,dialog=bottleEditorShell(`<div class="return-editor-heading"><span><strong class="bottle-editor-title">Registra reso linea</strong><small>Dopo la pesata indica il numero di pezzi e identifica il contenitore.</small></span><button type="button" id="openLineReturnsFromNew" class="return-archive-inside">Archivio resi${pending?` <b>${pending}</b>`:''}</button></div><label class="field">Linea di provenienza<select id="lineReturnLine">${names.map(name=>`<option value="${name}" ${name===selected?'selected':''}>Linea ${name}</option>`).join('')}</select></label><fieldset class="return-container-picker"><legend>Tipo di contenitore</legend><label><input type="radio" name="returnContainer" value="big" checked>${lineReturnBagVisual('big')} </label><label><input type="radio" name="returnContainer" value="medium">${lineReturnBagVisual('medium')}</label></fieldset><label class="field">Quantità dopo la pesata<input id="lineReturnPieces" type="number" inputmode="numeric" min="1" step="1" placeholder="Numero di pezzi"><small>Inserisci i pezzi, non il peso.</small></label><label class="field">Nome o barcode del contenitore<input id="lineReturnCode" autocomplete="off" placeholder="Scrivi il codice oppure scansionalo"></label><button type="button" id="scanLineReturnBarcode" class="return-scan-button">▣ Scansiona barcode</button><section id="lineReturnScannerBox" class="return-scanner-box" hidden><div id="lineReturnBarcodeReader"></div><small>Inquadra il barcode del Big Bag o Medium Bag</small></section><div class="line-quick-actions"><button type="button" class="primary" id="confirmLineReturn">Invia ai responsabili</button><button type="button" id="cancelLineReturn">Annulla</button></div>`);const scannerBox=dialog.querySelector('#lineReturnScannerBox'),codeInput=dialog.querySelector('#lineReturnCode'),stopScanner=()=>scanner?.stop().catch(()=>{});dialog.addEventListener('close',stopScanner,{once:true});dialog.querySelector('#openLineReturnsFromNew').onclick=()=>{dialog.close();showLineReturnsArchive()};dialog.querySelector('#cancelLineReturn').onclick=()=>dialog.close();dialog.querySelector('#scanLineReturnBarcode').onclick=async()=>{if(!window.Html5Qrcode)return toast('Lettore barcode non disponibile: scrivi il codice',true);scannerBox.hidden=false;try{scanner=new Html5Qrcode('lineReturnBarcodeReader');await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:250,height:150}},value=>{codeInput.value=value;toast('Barcode letto');stopScanner();scannerBox.hidden=true},()=>{})}catch{scannerBox.hidden=true;toast('Fotocamera non disponibile: scrivi il codice',true)}};dialog.querySelector('#confirmLineReturn').onclick=async()=>{const line=dialog.querySelector('#lineReturnLine').value,type=dialog.querySelector('[name="returnContainer"]:checked')?.value||'big',pieces=Math.floor(Number(dialog.querySelector('#lineReturnPieces').value||0)),containerCode=codeInput.value.trim();if(!names.includes(line))return toast('Scegli la linea di provenienza',true);if(pieces<=0)return toast('Inserisci il numero di pezzi',true);if(!containerCode)return toast('Scrivi o scansiona il barcode del contenitore',true);const record={id:crypto.randomUUID(),line,type,pieces,containerCode,status:'pending',createdBy:actor(),createdByRole:activeProfile()?.role||'',createdAt:now(),deviceId:currentDeviceId().slice(0,8).toUpperCase(),associatedBy:'',associatedAt:''};appState.lineReturns.unshift(record);appState.lineReturns=appState.lineReturns.slice(0,3000);event(appState.lines[line],`Reso ${type==='medium'?'Medium Bag':'Big Bag'} da associare: ${pieces.toLocaleString('it-IT')} pezzi · ${containerCode}`,{kind:'return'});await save();stopScanner();dialog.close();render();toast('Reso inviato ai responsabili')};}
function lineReturnRows(){const records=[...(appState.lineReturns||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));if(!records.length)return'<div class="return-archive-empty"><strong>Nessun reso registrato</strong><p>I nuovi resi compariranno qui.</p></div>';return records.map(item=>`<article class="return-record ${item.status==='associated'?'is-associated':'is-pending'}">${lineReturnBagVisual(item.type,item.pieces)}<div class="return-record-copy"><div><span class="history-line-badge">${esc(item.line)}</span><span class="return-status">${item.status==='associated'?'ASSOCIAZIONE CONFERMATA':'DA ASSOCIARE'}</span></div><strong>${esc(item.containerCode)}</strong><small>Registrato da ${esc(item.createdBy)} · ${showTime(item.createdAt)}</small>${item.status==='associated'?`<small>Confermato da ${esc(item.associatedBy)} · ${showTime(item.associatedAt)}</small>`:''}</div>${item.status!=='associated'&&isCT()?`<button type="button" class="primary" data-confirm-return="${item.id}">Conferma associazione avvenuta</button>`:''}</article>`).join('')}
function showLineReturnsArchive(){const previous=$('#lineReturnsDialog');if(previous)previous.remove();const pending=(appState.lineReturns||[]).filter(item=>item.status!=='associated').length,dialog=document.createElement('dialog');dialog.id='lineReturnsDialog';dialog.className='line-returns-dialog';dialog.innerHTML=`<div class="handover-archive-top"><div><small>RESI LINEA</small><h2>Big Bag e Medium Bag</h2><p>Quantità in pezzi e identificativo del contenitore.</p></div><button type="button" class="history-close">Chiudi ×</button></div><div class="return-archive-summary"><strong>${pending} da associare</strong><button type="button" id="newReturnFromArchive">＋ Nuovo reso</button></div><div class="return-record-list">${lineReturnRows()}</div>`;document.body.appendChild(dialog);dialog.querySelector('.history-close').onclick=()=>dialog.close();dialog.querySelector('#newReturnFromArchive').onclick=()=>{dialog.close();showLineReturnDialog()};dialog.querySelectorAll('[data-confirm-return]').forEach(button=>button.onclick=()=>confirmLineReturnAssociation(button.dataset.confirmReturn,dialog));dialog.onclose=()=>dialog.remove();dialog.showModal()}
async function confirmLineReturnAssociation(id,dialog){if(!isCT())return toast('Conferma riservata ai responsabili',true);const item=(appState.lineReturns||[]).find(record=>record.id===id);if(!item||item.status==='associated')return;item.status='associated';item.associatedBy=actor();item.associatedAt=now();event(appState.lines[item.line],`Associazione reso confermata: ${item.containerCode} · ${item.pieces.toLocaleString('it-IT')} pezzi`,{kind:'return'});await save();dialog.querySelector('.return-record-list').innerHTML=lineReturnRows();dialog.querySelector('.return-archive-summary strong').textContent=`${appState.lineReturns.filter(record=>record.status!=='associated').length} da associare`;dialog.querySelectorAll('[data-confirm-return]').forEach(button=>button.onclick=()=>confirmLineReturnAssociation(button.dataset.confirmReturn,dialog));renderLineReturnsWidget();toast('Associazione confermata')}

function renderChecklistHub(){const hub=$('#checklistApp'),data=loadDeviceDemo(),active=data.active,statusLabels={new:'Nuova',in_progress:'Presa in carico',resolved:'Riparata',closed:'Verificata e chiusa'},types=[['Muletti','Controlli di sicurezza e stato del mezzo','M'],['Transpallet elettrici','Controlli operativi, batteria e sicurezza','T'],['Macchine Sidel','Controlli dedicati alla macchina Sidel','S'],['Macchine Magic','Controlli dedicati alla macchina Magic','G']];hub.innerHTML=`<div class="area-topbar"><button id="checklistBack">← Scelta aree</button><span>Checklist mezzi e macchine</span><b class="demo-pill">DEMO</b></div><section class="area-welcome compact"><span class="area-eyebrow">Consegna digitale</span><h2>Dispositivo aziendale</h2><p>Presa, riconsegna e danni registrati con utente, data e ora.</p></section><section class="device-demo-grid"><article class="device-handover-card"><div class="device-card-heading"><span class="device-card-icon">▣</span><div><small>QUESTO DISPOSITIVO</small><strong>${esc(defaultDeviceLabel())}</strong></div></div>${active?`<div class="device-active-session"><span>Consegnato a</span><strong>${esc(active.user)}</strong><small>${showTime(active.at)} · ${esc(deviceConditionLabels[active.condition]||active.condition)}</small></div><button class="primary" id="returnDeviceDemo">Riconsegna dispositivo</button>`:`<div class="device-ready"><strong>Pronto per la consegna</strong><small>Se è in ordine bastano due tocchi.</small></div><button class="primary" id="takeDeviceDemo">Conferma presa dispositivo</button>`}</article><article class="shift-protected-card"><div><small>PROSSIMO CAMBIO TURNO</small><strong>${nextShiftBoundary().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</strong></div><b data-shift-countdown>--:--:--</b><p>Il sistema richiederà riconsegna e nuovo login personale.</p><button id="simulateShiftChange">Vedi simulazione</button></article></section><section class="device-reports-section"><div class="device-reports-heading"><div><span class="area-eyebrow">Checklist automatica</span><h2>Segnalazioni dispositivi</h2></div><span>${data.reports.length}</span></div>${data.reports.length?`<div class="device-report-list">${data.reports.map(report=>`<article class="device-report report-${report.status}"><div><span class="report-status">${esc(statusLabels[report.status]||report.status)}</span><strong>${esc(devicePartLabels[report.part]||report.description)}</strong><small>${esc(report.description)} · ${esc(report.phase)}</small><small>${esc(report.reportedBy)} · ${showTime(report.reportedAt)} · ${esc(report.device)}</small>${report.assignedTo?`<small>In carico a ${esc(report.assignedTo)}</small>`:''}</div>${report.status!=='closed'?`<button data-device-report="${report.id}">${report.status==='new'?'Prendi in carico':report.status==='in_progress'?'Segna riparata':'Verifica e chiudi'}</button>`:'<span class="report-done">✓</span>'}</article>`).join('')}</div>`:'<div class="device-report-empty"><strong>Nessun danno aperto</strong><p>Le segnalazioni fatte durante presa o riconsegna appariranno qui automaticamente.</p></div>'}</section>${data.history.length?`<details class="device-history"><summary>Ultime consegne (${data.history.length})</summary><div>${data.history.slice(0,8).map(item=>`<article><strong>${esc(item.user)} · ${esc(item.device)}</strong><span>Presa ${showTime(item.at)} · ${esc(deviceConditionLabels[item.condition]||item.condition)}</span><span>Riconsegna ${showTime(item.returnedAt)} · ${esc(deviceConditionLabels[item.finalCondition]||item.finalCondition)}</span></article>`).join('')}</div></details>`:''}<section class="machine-grid device-machines">${types.map(([name,description,icon])=>`<article class="machine-card"><span class="machine-icon" aria-hidden="true">${icon}</span><div><strong>${name}</strong><p>${description}</p><small>Apri checklist</small></div></article>`).join('')}</section>`;$('#checklistBack').onclick=()=>openArea('home');if($('#takeDeviceDemo'))$('#takeDeviceDemo').onclick=()=>showDeviceHandoverDialog('take');if($('#returnDeviceDemo'))$('#returnDeviceDemo').onclick=()=>showDeviceHandoverDialog('return');$('#simulateShiftChange').onclick=showShiftChangeDemo;hub.querySelectorAll('[data-device-report]').forEach(button=>button.onclick=()=>updateDeviceReport(button.dataset.deviceReport));updateShiftCountdown()}
const FORKLIFT_DEMO_KEY='reparto-live-forklifts-demo-v1';
const forkliftIssueLabels={forks:'Forche',wheels:'Ruote o gomme',brakes:'Freni',battery:'Batteria o ricarica',lights:'Luci o segnalatori',leak:'Perdita di liquidi',body:'Urto o danno struttura',controls:'Comandi di guida',other:'Altro problema'};
const forkliftSeverityLabels={attention:'Da controllare',urgent:'Urgente',stopped:'Muletto fermo'};
function loadForkliftDemo(){try{const saved=JSON.parse(localStorage.getItem(FORKLIFT_DEMO_KEY)||'null');if(saved?.vehicles?.length===5&&Array.isArray(saved.reports))return saved}catch{}return{vehicles:Array.from({length:5},(_,index)=>({id:`forklift-${index+1}`,name:`Muletto ${index+1}`,reference:''})),reports:[]}}
function saveForkliftDemo(data){localStorage.setItem(FORKLIFT_DEMO_KEY,JSON.stringify(data))}
function forkliftDrawing(){return `<img src="./assets/forklifts/muletto-checklist.png" alt="Muletto elettrico giallo e nero">`}
function forkliftFleetSection(){const data=loadForkliftDemo(),open=data.reports.filter(report=>report.status!=='closed');return `<section class="forklift-demo-section"><div class="forklift-section-heading"><div><span class="area-eyebrow">Checklist mezzi</span><h2>Muletti</h2><p>Cinque mezzi provvisori. I numeri di riferimento verranno aggiunti più avanti.</p></div><span>${open.length} aperte</span></div><div class="forklift-grid">${data.vehicles.map((vehicle,index)=>{const pending=open.filter(report=>report.vehicleId===vehicle.id).length;return `<article class="forklift-card ${pending?'has-issue':''}"><span class="forklift-number">${index+1}</span><div class="forklift-illustration">${forkliftDrawing()}</div><strong>${esc(vehicle.reference||vehicle.name)}</strong><small>${vehicle.reference?'Muletto':'Riferimento provvisorio'}</small>${pending?`<b class="forklift-alert">${pending} ${pending===1?'problema aperto':'problemi aperti'}</b>`:'<b class="forklift-ok">Nessun problema aperto</b>'}<button type="button" data-forklift-report="${vehicle.id}">Segnala problema</button></article>`}).join('')}</div>${open.length?`<div class="forklift-open-reports"><h3>Problemi segnalati</h3>${open.map(report=>`<article><span class="report-status">${esc(forkliftSeverityLabels[report.severity])}</span><div><strong>${esc(report.vehicleName)} · ${esc(forkliftIssueLabels[report.issue])}</strong><small>${esc(report.note||'Nessuna nota')} · ${esc(report.reportedBy)} · ${showTime(report.reportedAt)}</small></div><button type="button" data-close-forklift-report="${report.id}">Chiudi</button></article>`).join('')}</div>`:''}</section>`}
function showForkliftReportDialog(vehicleId){const data=loadForkliftDemo(),vehicle=data.vehicles.find(item=>item.id===vehicleId);if(!vehicle)return;const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Segnala problema · ${esc(vehicle.reference||vehicle.name)}</strong><p class="device-dialog-intro">Seleziona rapidamente il difetto riscontrato sul muletto.</p><label class="field">Tipo di problema<select id="forkliftIssue">${Object.entries(forkliftIssueLabels).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><fieldset class="forklift-severity-picker"><legend>Gravità</legend>${Object.entries(forkliftSeverityLabels).map(([value,label],index)=>`<label><input type="radio" name="forkliftSeverity" value="${value}" ${index===0?'checked':''}><span>${value==='attention'?'!':value==='urgent'?'!!':'STOP'}</span><b>${label}</b></label>`).join('')}</fieldset><label class="field">Nota facoltativa<textarea id="forkliftIssueNote" maxlength="180" placeholder="Descrivi brevemente cosa hai notato"></textarea></label><button type="button" class="primary device-dialog-confirm" id="confirmForkliftReport">Invia segnalazione</button>`);dialog.querySelector('#confirmForkliftReport').onclick=()=>{const issue=dialog.querySelector('#forkliftIssue').value,severity=dialog.querySelector('[name="forkliftSeverity"]:checked')?.value||'attention',note=dialog.querySelector('#forkliftIssueNote').value.trim();if(issue==='other'&&!note)return toast('Descrivi brevemente il problema',true);data.reports.unshift({id:crypto.randomUUID(),vehicleId:vehicle.id,vehicleName:vehicle.reference||vehicle.name,issue,severity,note,status:'new',reportedBy:actor(),reportedAt:now()});data.reports=data.reports.slice(0,100);saveForkliftDemo(data);dialog.close();renderForkliftHub();toast('Problema del muletto segnalato')}}
function closeForkliftReport(reportId){const data=loadForkliftDemo(),report=data.reports.find(item=>item.id===reportId);if(!report)return;report.status='closed';report.closedBy=actor();report.closedAt=now();saveForkliftDemo(data);renderForkliftHub();toast('Segnalazione chiusa')}
function renderForkliftHub(){const hub=$('#checklistApp');hub.innerHTML=`<div class="area-topbar"><button id="forkliftBack">← Checklist</button><span>Muletti</span></div>${forkliftFleetSection()}`;$('#forkliftBack').onclick=renderChecklistHub;hub.querySelectorAll('[data-forklift-report]').forEach(button=>button.onclick=()=>showForkliftReportDialog(button.dataset.forkliftReport));hub.querySelectorAll('[data-close-forklift-report]').forEach(button=>button.onclick=()=>closeForkliftReport(button.dataset.closeForkliftReport));hub.scrollTo?.({top:0,behavior:'smooth'})}
function mountForkliftDemo(){const hub=$('#checklistApp'),forkliftCard=[...hub.querySelectorAll('.device-machines .machine-card')].find(card=>card.querySelector('strong')?.textContent.trim()==='Muletti');if(!forkliftCard)return;const open=loadForkliftDemo().reports.filter(report=>report.status!=='closed').length;forkliftCard.classList.add('machine-card-openable');forkliftCard.tabIndex=0;forkliftCard.setAttribute('role','button');forkliftCard.setAttribute('aria-label','Apri checklist muletti');const status=forkliftCard.querySelector('small');if(status){status.textContent=open?`${open} ${open===1?'problema aperto':'problemi aperti'}`:'Apri checklist';status.classList.toggle('has-alert',open>0)}forkliftCard.insertAdjacentHTML('beforeend','<span class="machine-card-arrow" aria-hidden="true">→</span>');forkliftCard.onclick=renderForkliftHub;forkliftCard.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();renderForkliftHub()}}}
const TRANSPALLET_DEMO_KEY='reparto-live-transpallet-demo-v1';
const SMALL_TRANSPALLET_DEMO_KEY='reparto-live-small-transpallet-demo-v1';
const transpalletIssueLabels={forks:'Forche',wheels:'Ruote o rulli',brakes:'Freno',battery:'Batteria o ricarica',tiller:'Timone o comandi',lifting:'Sollevamento o montante',alarm:'Avvisatore o segnalatori',leak:'Perdita di liquidi',body:'Urto o danno struttura',other:'Altro problema'};
const transpalletSeverityLabels={attention:'Da controllare',urgent:'Urgente',stopped:'Transpallet fermo'};
function loadTranspalletDemo(){try{const saved=JSON.parse(localStorage.getItem(TRANSPALLET_DEMO_KEY)||'null');if(saved?.vehicles?.length===5&&Array.isArray(saved.reports))return saved}catch{}return{vehicles:Array.from({length:5},(_,index)=>({id:`transpallet-${index+1}`,name:`Transpallet ${index+1}`,reference:'',type:'Tipo 1'})),reports:[]}}
function saveTranspalletDemo(data){localStorage.setItem(TRANSPALLET_DEMO_KEY,JSON.stringify(data))}
function loadSmallTranspalletDemo(){try{const saved=JSON.parse(localStorage.getItem(SMALL_TRANSPALLET_DEMO_KEY)||'null');if(saved?.vehicles?.length===5&&Array.isArray(saved.reports))return saved}catch{}return{vehicles:Array.from({length:5},(_,index)=>({id:`small-transpallet-${index+1}`,name:`Transpallet piccolo ${index+1}`,reference:'',type:'Piccolo'})),reports:[]}}
function saveSmallTranspalletDemo(data){localStorage.setItem(SMALL_TRANSPALLET_DEMO_KEY,JSON.stringify(data))}
function transpalletDrawing(){return `<img src="./assets/transpallet/transpallet-elettrico-tipo-1.png" alt="Transpallet elettrico con montante alto e forche lunghe">`}
function smallTranspalletDrawing(){return `<img src="./assets/transpallet/transpallet-elettrico-piccolo.png" alt="Transpallet elettrico piccolo con timone e forche basse">`}
function transpalletFleetSection(){const data=loadTranspalletDemo(),open=data.reports.filter(report=>report.status!=='closed');return `<section class="forklift-demo-section transpallet-demo-section"><div class="forklift-section-heading"><div><span class="area-eyebrow">Checklist mezzi</span><h2>Transpallet grandi</h2><p>Con montante alto · cinque mezzi provvisori. I numeri di riferimento verranno aggiunti più avanti.</p></div><span>${open.length} aperte</span></div><div class="forklift-grid transpallet-grid">${data.vehicles.map((vehicle,index)=>{const pending=open.filter(report=>report.vehicleId===vehicle.id).length;return `<article class="forklift-card transpallet-card ${pending?'has-issue':''}"><span class="forklift-number">${index+1}</span><span class="transpallet-type">Grande</span><div class="forklift-illustration transpallet-illustration">${transpalletDrawing()}</div><strong>${esc(vehicle.reference||vehicle.name)}</strong><small>${vehicle.reference?'Transpallet elettrico grande':'Riferimento provvisorio'}</small>${pending?`<b class="forklift-alert">${pending} ${pending===1?'problema aperto':'problemi aperti'}</b>`:'<b class="forklift-ok">Nessun problema aperto</b>'}<button type="button" data-transpallet-report="${vehicle.id}">Segnala problema</button></article>`}).join('')}</div>${open.length?`<div class="forklift-open-reports"><h3>Problemi segnalati · grandi</h3>${open.map(report=>`<article><span class="report-status">${esc(transpalletSeverityLabels[report.severity])}</span><div><strong>${esc(report.vehicleName)} · ${esc(transpalletIssueLabels[report.issue])}</strong><small>${esc(report.note||'Nessuna nota')} · ${esc(report.reportedBy)} · ${showTime(report.reportedAt)}</small></div><button type="button" data-close-transpallet-report="${report.id}">Chiudi</button></article>`).join('')}</div>`:''}</section>`}
function smallTranspalletFleetSection(){const data=loadSmallTranspalletDemo(),open=data.reports.filter(report=>report.status!=='closed');return `<section class="forklift-demo-section transpallet-demo-section small-transpallet-section"><div class="forklift-section-heading"><div><span class="area-eyebrow">Checklist mezzi</span><h2>Transpallet piccoli</h2><p>Compatti a forche basse · cinque mezzi provvisori. I numeri di riferimento verranno aggiunti più avanti.</p></div><span>${open.length} aperte</span></div><div class="forklift-grid transpallet-grid">${data.vehicles.map((vehicle,index)=>{const pending=open.filter(report=>report.vehicleId===vehicle.id).length;return `<article class="forklift-card transpallet-card small-transpallet-card ${pending?'has-issue':''}"><span class="forklift-number">${index+1}</span><span class="transpallet-type">Piccolo</span><div class="forklift-illustration transpallet-illustration">${smallTranspalletDrawing()}</div><strong>${esc(vehicle.reference||vehicle.name)}</strong><small>${vehicle.reference?'Transpallet elettrico piccolo':'Riferimento provvisorio'}</small>${pending?`<b class="forklift-alert">${pending} ${pending===1?'problema aperto':'problemi aperti'}</b>`:'<b class="forklift-ok">Nessun problema aperto</b>'}<button type="button" data-small-transpallet-report="${vehicle.id}">Segnala problema</button></article>`}).join('')}</div>${open.length?`<div class="forklift-open-reports"><h3>Problemi segnalati · piccoli</h3>${open.map(report=>`<article><span class="report-status">${esc(transpalletSeverityLabels[report.severity])}</span><div><strong>${esc(report.vehicleName)} · ${esc(transpalletIssueLabels[report.issue])}</strong><small>${esc(report.note||'Nessuna nota')} · ${esc(report.reportedBy)} · ${showTime(report.reportedAt)}</small></div><button type="button" data-close-small-transpallet-report="${report.id}">Chiudi</button></article>`).join('')}</div>`:''}</section>`}
function showTranspalletReportDialog(vehicleId){const data=loadTranspalletDemo(),vehicle=data.vehicles.find(item=>item.id===vehicleId);if(!vehicle)return;const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Segnala problema · ${esc(vehicle.reference||vehicle.name)}</strong><p class="device-dialog-intro">Seleziona rapidamente il difetto riscontrato sul transpallet elettrico.</p><label class="field">Tipo di problema<select id="transpalletIssue">${Object.entries(transpalletIssueLabels).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><fieldset class="forklift-severity-picker"><legend>Gravità</legend>${Object.entries(transpalletSeverityLabels).map(([value,label],index)=>`<label><input type="radio" name="transpalletSeverity" value="${value}" ${index===0?'checked':''}><span>${value==='attention'?'!':value==='urgent'?'!!':'STOP'}</span><b>${label}</b></label>`).join('')}</fieldset><label class="field">Nota facoltativa<textarea id="transpalletIssueNote" maxlength="180" placeholder="Descrivi brevemente cosa hai notato"></textarea></label><button type="button" class="primary device-dialog-confirm" id="confirmTranspalletReport">Invia segnalazione</button>`);dialog.querySelector('#confirmTranspalletReport').onclick=()=>{const issue=dialog.querySelector('#transpalletIssue').value,severity=dialog.querySelector('[name="transpalletSeverity"]:checked')?.value||'attention',note=dialog.querySelector('#transpalletIssueNote').value.trim();if(issue==='other'&&!note)return toast('Descrivi brevemente il problema',true);data.reports.unshift({id:crypto.randomUUID(),vehicleId:vehicle.id,vehicleName:vehicle.reference||vehicle.name,issue,severity,note,status:'new',reportedBy:actor(),reportedAt:now()});data.reports=data.reports.slice(0,100);saveTranspalletDemo(data);dialog.close();renderTranspalletHub();toast('Problema del transpallet segnalato')}}
function closeTranspalletReport(reportId){const data=loadTranspalletDemo(),report=data.reports.find(item=>item.id===reportId);if(!report)return;report.status='closed';report.closedBy=actor();report.closedAt=now();saveTranspalletDemo(data);renderTranspalletHub();toast('Segnalazione chiusa')}
function showSmallTranspalletReportDialog(vehicleId){const data=loadSmallTranspalletDemo(),vehicle=data.vehicles.find(item=>item.id===vehicleId);if(!vehicle)return;const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Segnala problema · ${esc(vehicle.reference||vehicle.name)}</strong><p class="device-dialog-intro">Seleziona rapidamente il difetto riscontrato sul transpallet piccolo.</p><label class="field">Tipo di problema<select id="smallTranspalletIssue">${Object.entries(transpalletIssueLabels).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><fieldset class="forklift-severity-picker"><legend>Gravità</legend>${Object.entries(transpalletSeverityLabels).map(([value,label],index)=>`<label><input type="radio" name="smallTranspalletSeverity" value="${value}" ${index===0?'checked':''}><span>${value==='attention'?'!':value==='urgent'?'!!':'STOP'}</span><b>${label}</b></label>`).join('')}</fieldset><label class="field">Nota facoltativa<textarea id="smallTranspalletIssueNote" maxlength="180" placeholder="Descrivi brevemente cosa hai notato"></textarea></label><button type="button" class="primary device-dialog-confirm" id="confirmSmallTranspalletReport">Invia segnalazione</button>`);dialog.querySelector('#confirmSmallTranspalletReport').onclick=()=>{const issue=dialog.querySelector('#smallTranspalletIssue').value,severity=dialog.querySelector('[name="smallTranspalletSeverity"]:checked')?.value||'attention',note=dialog.querySelector('#smallTranspalletIssueNote').value.trim();if(issue==='other'&&!note)return toast('Descrivi brevemente il problema',true);data.reports.unshift({id:crypto.randomUUID(),vehicleId:vehicle.id,vehicleName:vehicle.reference||vehicle.name,issue,severity,note,status:'new',reportedBy:actor(),reportedAt:now()});data.reports=data.reports.slice(0,100);saveSmallTranspalletDemo(data);dialog.close();renderTranspalletHub();toast('Problema del transpallet piccolo segnalato')}}
function closeSmallTranspalletReport(reportId){const data=loadSmallTranspalletDemo(),report=data.reports.find(item=>item.id===reportId);if(!report)return;report.status='closed';report.closedBy=actor();report.closedAt=now();saveSmallTranspalletDemo(data);renderTranspalletHub();toast('Segnalazione chiusa')}
function renderTranspalletHub(){const hub=$('#checklistApp');hub.innerHTML=`<div class="area-topbar"><button id="transpalletBack">← Checklist</button><span>Transpallet elettrici</span></div><div class="transpallet-category-intro"><strong>10 mezzi in 2 tipologie</strong><span>5 grandi · 5 piccoli</span></div>${transpalletFleetSection()}${smallTranspalletFleetSection()}`;$('#transpalletBack').onclick=renderChecklistHub;hub.querySelectorAll('[data-transpallet-report]').forEach(button=>button.onclick=()=>showTranspalletReportDialog(button.dataset.transpalletReport));hub.querySelectorAll('[data-close-transpallet-report]').forEach(button=>button.onclick=()=>closeTranspalletReport(button.dataset.closeTranspalletReport));hub.querySelectorAll('[data-small-transpallet-report]').forEach(button=>button.onclick=()=>showSmallTranspalletReportDialog(button.dataset.smallTranspalletReport));hub.querySelectorAll('[data-close-small-transpallet-report]').forEach(button=>button.onclick=()=>closeSmallTranspalletReport(button.dataset.closeSmallTranspalletReport));hub.scrollTo?.({top:0,behavior:'smooth'})}
function mountTranspalletDemo(){const hub=$('#checklistApp'),card=[...hub.querySelectorAll('.device-machines .machine-card')].find(item=>item.querySelector('strong')?.textContent.trim()==='Transpallet elettrici');if(!card)return;const open=[...loadTranspalletDemo().reports,...loadSmallTranspalletDemo().reports].filter(report=>report.status!=='closed').length;card.classList.add('machine-card-openable');card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','Apri checklist di 5 transpallet grandi e 5 piccoli');const status=card.querySelector('small');if(status){status.textContent=open?`${open} ${open===1?'problema aperto':'problemi aperti'}`:'5 grandi · 5 piccoli';status.classList.toggle('has-alert',open>0)}card.insertAdjacentHTML('beforeend','<span class="machine-card-arrow" aria-hidden="true">→</span>');card.onclick=renderTranspalletHub;card.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();renderTranspalletHub()}}}
