function sidelFleetSection(){const data=loadSidelDemo(),open=data.reports.filter(report=>report.status!=='closed');return `<section class="forklift-demo-section sidel-demo-section"><div class="forklift-section-heading"><div><span class="area-eyebrow">Checklist macchine</span><h2>Macchine Sidel</h2><p>Quattro macchine identificate con il loro numero di riferimento.</p></div><span>${open.length} aperte</span></div><div class="forklift-grid sidel-grid">${data.machines.map(machine=>{const pending=open.filter(report=>report.machineId===machine.id).length;return `<article class="forklift-card sidel-card ${pending?'has-issue':''}"><span class="sidel-reference">${esc(machine.reference)}</span><div class="forklift-illustration sidel-illustration">${sidelDrawing()}</div><strong>${esc(machine.name)}</strong><small>Codice macchina ${esc(machine.reference)}</small>${pending?`<b class="forklift-alert">${pending} ${pending===1?'problema aperto':'problemi aperti'}</b>`:'<b class="forklift-ok">Nessun problema aperto</b>'}<button type="button" data-sidel-report="${machine.id}">Segnala problema</button></article>`}).join('')}</div>${open.length?`<div class="forklift-open-reports"><h3>Problemi Sidel segnalati</h3>${open.map(report=>`<article><span class="report-status">${esc(sidelSeverityLabels[report.severity])}</span><div><strong>${esc(report.machineName)} · ${esc(sidelIssueLabels[report.issue])}</strong><small>${esc(report.note||'Nessuna nota')} · ${esc(report.reportedBy)} · ${showTime(report.reportedAt)}</small></div><button type="button" data-close-sidel-report="${report.id}">Chiudi</button></article>`).join('')}</div>`:''}</section>`}
function showSidelReportDialog(machineId){const data=loadSidelDemo(),machine=data.machines.find(item=>item.id===machineId);if(!machine)return;const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Segnala problema · ${esc(machine.reference)} ${esc(machine.name)}</strong><p class="device-dialog-intro">Seleziona rapidamente la problematica riscontrata sulla macchina.</p><label class="field">Tipo di problema<select id="sidelIssue">${Object.entries(sidelIssueLabels).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><fieldset class="forklift-severity-picker"><legend>Gravità</legend>${Object.entries(sidelSeverityLabels).map(([value,label],index)=>`<label><input type="radio" name="sidelSeverity" value="${value}" ${index===0?'checked':''}><span>${value==='attention'?'!':value==='urgent'?'!!':'STOP'}</span><b>${label}</b></label>`).join('')}</fieldset><label class="field">Nota facoltativa<textarea id="sidelIssueNote" maxlength="180" placeholder="Descrivi brevemente cosa hai notato"></textarea></label><button type="button" class="primary device-dialog-confirm" id="confirmSidelReport">Invia segnalazione</button>`);dialog.querySelector('#confirmSidelReport').onclick=()=>{const issue=dialog.querySelector('#sidelIssue').value,severity=dialog.querySelector('[name="sidelSeverity"]:checked')?.value||'attention',note=dialog.querySelector('#sidelIssueNote').value.trim();if(issue==='other'&&!note)return toast('Descrivi brevemente il problema',true);data.reports.unshift({id:crypto.randomUUID(),machineId:machine.id,machineName:`${machine.reference} ${machine.name}`,issue,severity,note,status:'new',reportedBy:actor(),reportedAt:now()});data.reports=data.reports.slice(0,100);saveSidelDemo(data);dialog.close();renderSidelHub();toast('Problema della Sidel segnalato')}}
function closeSidelReport(reportId){const data=loadSidelDemo(),report=data.reports.find(item=>item.id===reportId);if(!report)return;report.status='closed';report.closedBy=actor();report.closedAt=now();saveSidelDemo(data);renderSidelHub();toast('Segnalazione chiusa')}
function renderSidelHub(){const hub=$('#checklistApp');hub.innerHTML=`<div class="area-topbar"><button id="sidelBack">← Checklist</button><span>Macchine Sidel</span></div>${sidelFleetSection()}`;$('#sidelBack').onclick=renderChecklistHub;hub.querySelectorAll('[data-sidel-report]').forEach(button=>button.onclick=()=>showSidelReportDialog(button.dataset.sidelReport));hub.querySelectorAll('[data-close-sidel-report]').forEach(button=>button.onclick=()=>closeSidelReport(button.dataset.closeSidelReport));hub.scrollTo?.({top:0,behavior:'smooth'})}
function mountSidelDemo(){const hub=$('#checklistApp'),card=[...hub.querySelectorAll('.device-machines .machine-card')].find(item=>item.querySelector('strong')?.textContent.trim()==='Macchine Sidel');if(!card)return;const open=loadSidelDemo().reports.filter(report=>report.status!=='closed').length;card.classList.add('machine-card-openable');card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','Apri checklist delle quattro macchine Sidel');const status=card.querySelector('small');if(status){status.textContent=open?`${open} ${open===1?'problema aperto':'problemi aperti'}`:'4 macchine';status.classList.toggle('has-alert',open>0)}card.insertAdjacentHTML('beforeend','<span class="machine-card-arrow" aria-hidden="true">→</span>');card.onclick=renderSidelHub;card.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();renderSidelHub()}}}
const MAGIC_DEMO_KEY='reparto-live-magic-demo-v1';
const magicIssueLabels={doors:'Sportelli o protezioni',emergency:'Emergenze o sicurezze',controls:'Comandi o pannello',mould:'Gruppo stampi',mechanical:'Parte meccanica',electrical:'Parte elettrica',pneumatic:'Aria o circuito pneumatico',leak:'Perdita di liquidi',noise:'Rumore o vibrazione anomala',cleaning:'Pulizia macchina',other:'Altro problema'};
