function loadMagicDemo(){try{const saved=JSON.parse(localStorage.getItem(MAGIC_DEMO_KEY)||'null');if(saved?.machines?.length===2&&Array.isArray(saved.reports))return saved}catch{}return{machines:[{id:'magic-bm10',reference:'0025',name:'BM10'},{id:'magic-bm11',reference:'0028',name:'BM11'}],reports:[]}}
