function closeMagicReport(reportId){const data=loadMagicDemo(),report=data.reports.find(item=>item.id===reportId);if(!report)return;report.status='closed';report.closedBy=actor();report.closedAt=now();saveMagicDemo(data);renderMagicHub();toast('Segnalazione chiusa')}
