function mountMagicDemo(){const hub=$('#checklistApp'),card=[...hub.querySelectorAll('.device-machines .machine-card')].find(item=>item.querySelector('strong')?.textContent.trim()==='Macchine Magic');if(!card)return;const open=loadMagicDemo().reports.filter(report=>report.status!=='closed').length;card.classList.add('machine-card-openable');card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','Apri checklist delle due macchine Magic');const status=card.querySelector('small');if(status){status.textContent=open?`${open} ${open===1?'problema aperto':'problemi aperti'}`:'2 macchine';status.classList.toggle('has-alert',open>0)}card.insertAdjacentHTML('beforeend','<span class="machine-card-arrow" aria-hidden="true">→</span>');card.onclick=renderMagicHub;card.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();renderMagicHub()}}}
const generalReportStatusLabels={new:'Nuova',in_progress:'Presa in carico',resolved:'Risolta',closed:'Chiusa'};
const generalReportSeverityLabels={attention:'Da controllare',urgent:'Urgente',danger:'Pericolo: isolare la zona'};
function queueGeneralReportEvent(text){pendingAudit.push({id:crypto.randomUUID(),line:'Generale',text,actor:actor(),actorRole:activeProfile()?.role||'',at:now(),kind:'general',recipientUserId:'',deviceId:currentDeviceId().slice(0,8).toUpperCase(),deviceLabel:defaultDeviceLabel()})}
async function uploadGeneralReportPhoto(file,id){if(previewActive())throw Error('In anteprima le fotografie non vengono caricate');const blob=await resizePhoto(file),path=`general-reports/${id}.jpg`;const {error}=await db.storage.from('bottle-photos').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw error;const {data}=db.storage.from('bottle-photos').getPublicUrl(path);return `${data.publicUrl}?v=${Date.now()}`}
function previewGeneralReportPhoto(input){const file=input.files?.[0],preview=$('#generalReportPhotoPreview');if(!file||!preview)return;const url=URL.createObjectURL(file);preview.onload=()=>URL.revokeObjectURL(url);preview.onerror=()=>{URL.revokeObjectURL(url);preview.hidden=true;toast('Foto non leggibile: prova a sceglierla dalla galleria',true)};preview.src=url;preview.hidden=false}
function showGeneralReportDialog(){const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Segnala qualcosa di rotto</strong><p class="device-dialog-intro">Fai o scegli una foto, indica dove si trova e descrivi brevemente il problema.</p><label class="field general-photo-field">Foto del problema<input id="generalReportPhoto" type="file" accept="image/*,.heic,.heif" onchange="previewGeneralReportPhoto(this)"><small>Dal telefono puoi scegliere Fotocamera oppure Libreria foto.</small></label><img id="generalReportPhotoPreview" class="general-report-photo-preview" hidden alt="Anteprima del problema"><label class="field">Dove si trova?<input id="generalReportLocation" maxlength="100" placeholder="Es. corridoio linea KB, vicino alla porta"></label><label class="field">Che cosa è rotto?<textarea id="generalReportDescription" maxlength="300" placeholder="Descrivi il problema in poche parole"></textarea></label><fieldset class="forklift-severity-picker general-report-severity"><legend>Priorità</legend>${Object.entries(generalReportSeverityLabels).map(([value,label],index)=>`<label><input type="radio" name="generalReportSeverity" value="${value}" ${index===0?'checked':''}><span>${value==='attention'?'!':value==='urgent'?'!!':'⚠'}</span><b>${label}</b></label>`).join('')}</fieldset><div class="general-report-identity"><span>La segnalazione sarà inviata da</span><strong>${esc(actor())}</strong><small>${esc(roleLabels[activeProfile()?.role]||activeProfile()?.role||'Utente')} · ${esc(defaultDeviceLabel())}</small></div><div class="line-quick-actions"><button type="button" class="primary" id="confirmGeneralReport">Invia segnalazione</button><button type="button" id="cancelGeneralReport">Annulla</button></div>`);dialog.querySelector('#cancelGeneralReport').onclick=()=>dialog.close();dialog.querySelector('#confirmGeneralReport').onclick=async()=>{const button=dialog.querySelector('#confirmGeneralReport'),file=dialog.querySelector('#generalReportPhoto').files?.[0],location=dialog.querySelector('#generalReportLocation').value.trim(),description=dialog.querySelector('#generalReportDescription').value.trim(),severity=dialog.querySelector('[name="generalReportSeverity"]:checked')?.value||'attention';if(!file)return toast('Scatta o scegli una foto del problema',true);if(!location)return toast('Indica dove si trova',true);if(!description)return toast('Descrivi brevemente che cosa è rotto',true);const id=crypto.randomUUID();try{button.disabled=true;button.textContent='Invio in corso…';const photoUrl=await uploadGeneralReportPhoto(file,id),record={id,photoUrl,location,description,severity,status:'new',reportedBy:actor(),reportedById:activeProfile()?.id||session?.user?.id||'',reportedByRole:activeProfile()?.role||'',reportedAt:now(),deviceId:currentDeviceId().slice(0,8).toUpperCase(),deviceLabel:defaultDeviceLabel(),assignedTo:'',assignedAt:'',resolvedBy:'',resolvedAt:'',closedBy:'',closedAt:''};appState.generalReports.unshift(record);appState.generalReports=appState.generalReports.slice(0,1000);queueGeneralReportEvent(`Nuova segnalazione generale: ${location} · ${description}`);await save();dialog.close();renderChecklistHub();toast('Segnalazione inviata')}catch(error){button.disabled=false;button.textContent='Invia segnalazione';toast(error.message||'Impossibile inviare la segnalazione',true)}}}
function generalReportCard(report){const action=report.status==='new'?'Prendi in carico':report.status==='in_progress'?'Segna risolto':report.status==='resolved'?'Verifica e chiudi':'';return `<article class="general-report-card report-${esc(report.status)}"><button type="button" class="general-report-image" data-view-general-photo="${encodeURIComponent(report.photoUrl||'')}"><img src="${esc(report.photoUrl||'')}" alt="Foto segnalazione: ${esc(report.description)}"></button><div class="general-report-copy"><div><span class="report-status">${esc(generalReportStatusLabels[report.status]||report.status)}</span><span class="general-report-priority priority-${esc(report.severity)}">${esc(generalReportSeverityLabels[report.severity]||report.severity)}</span></div><strong>${esc(report.location)}</strong><p>${esc(report.description)}</p><small>Segnalato da ${esc(report.reportedBy)} · ${showTime(report.reportedAt)}</small><small>${esc(report.deviceLabel||report.deviceId||'Dispositivo non indicato')}</small>${report.assignedTo?`<small>In carico a ${esc(report.assignedTo)}</small>`:''}${report.resolvedBy?`<small>Risolto da ${esc(report.resolvedBy)} · ${showTime(report.resolvedAt)}</small>`:''}</div>${action&&isCT()?`<button type="button" class="general-report-action" data-general-report-action="${report.id}">${action}</button>`:report.status==='closed'?'<span class="report-done">✓</span>':''}</article>`}
function showGeneralReportPhoto(url){if(!url)return;const dialog=bottleEditorShell(`<strong class="bottle-editor-title">Foto della segnalazione</strong><img class="general-report-photo-full" src="${esc(url)}" alt="Foto ingrandita della segnalazione"><button type="button" class="primary device-dialog-confirm" id="closeGeneralPhoto">Chiudi</button>`);dialog.querySelector('#closeGeneralPhoto').onclick=()=>dialog.close()}
function bindGeneralReportActions(root){root.querySelectorAll('[data-general-report-action]').forEach(button=>button.onclick=()=>updateGeneralReport(button.dataset.generalReportAction));root.querySelectorAll('[data-view-general-photo]').forEach(button=>button.onclick=()=>showGeneralReportPhoto(decodeURIComponent(button.dataset.viewGeneralPhoto)))}
function showGeneralReportsArchive(){const existing=$('#generalReportsDialog');if(existing)existing.remove();const reports=[...(appState.generalReports||[])].sort((a,b)=>new Date(b.reportedAt)-new Date(a.reportedAt)),dialog=document.createElement('dialog');dialog.id='generalReportsDialog';dialog.className='general-reports-dialog';dialog.innerHTML=`<div class="handover-archive-top"><div><small>CHECKLIST GENERALE</small><h2>Segnalazioni reparto</h2><p>Foto, posizione, autore e stato di ogni problema.</p></div><button type="button" class="history-close">Chiudi ×</button></div><div class="general-report-archive-tools"><button type="button" class="primary" id="newGeneralReportFromArchive">＋ Nuova segnalazione</button><span>${reports.filter(item=>item.status!=='closed').length} aperte</span></div><div class="general-report-list">${reports.length?reports.map(generalReportCard).join(''):'<div class="device-report-empty"><strong>Nessuna segnalazione generale</strong><p>Le nuove segnalazioni compariranno qui.</p></div>'}</div>`;document.body.appendChild(dialog);dialog.querySelector('.history-close').onclick=()=>dialog.close();dialog.querySelector('#newGeneralReportFromArchive').onclick=()=>{dialog.close();showGeneralReportDialog()};bindGeneralReportActions(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal()}
async function updateGeneralReport(id){if(!isCT())return toast('Operazione riservata ai responsabili',true);const report=(appState.generalReports||[]).find(item=>item.id===id);if(!report)return;if(report.status==='new'){report.status='in_progress';report.assignedTo=actor();report.assignedAt=now();queueGeneralReportEvent(`Segnalazione presa in carico: ${report.location}`)}else if(report.status==='in_progress'){report.status='resolved';report.resolvedBy=actor();report.resolvedAt=now();queueGeneralReportEvent(`Segnalazione risolta: ${report.location}`)}else if(report.status==='resolved'){report.status='closed';report.closedBy=actor();report.closedAt=now();queueGeneralReportEvent(`Segnalazione verificata e chiusa: ${report.location}`)}await save();const archive=$('#generalReportsDialog');if(archive){archive.close();showGeneralReportsArchive()}else renderChecklistHub();toast('Stato della segnalazione aggiornato')}
function mountGeneralReports(){const hub=$('#checklistApp'),topbar=hub.querySelector('.area-topbar');if(!topbar)return;const reports=[...(appState.generalReports||[])].sort((a,b)=>new Date(b.reportedAt)-new Date(a.reportedAt)),open=reports.filter(item=>item.status!=='closed'),section=document.createElement('section');section.className='general-report-widget';section.innerHTML=`<div class="general-report-widget-heading"><span class="general-report-widget-icon">⚠${open.length?`<b>${open.length}</b>`:''}</span><div><span class="area-eyebrow">Segnalazioni generali</span><h2>Qualcosa di rotto?</h2><p>Scatta una foto e indica dove si trova.</p></div></div><div class="general-report-widget-actions"><button type="button" class="primary" id="newGeneralReport">＋ Segnala problema</button><button type="button" id="openGeneralReports">Archivio${open.length?` · ${open.length} aperte`:''}</button></div>${open.length?`<div class="general-report-preview-list">${open.slice(0,2).map(generalReportCard).join('')}</div>`:''}`;topbar.insertAdjacentElement('afterend',section);section.querySelector('#newGeneralReport').onclick=showGeneralReportDialog;section.querySelector('#openGeneralReports').onclick=showGeneralReportsArchive;bindGeneralReportActions(section)}
