function adminUserRow(u,statusLabel){const search=`${u.display_name||''} ${u.username||''} ${u.email||''} ${roleLabels[u.role]||u.role} ${u.team_code||''}`.toLowerCase(),roles=['ct','vice_ct','processista','operator','carrellista','logistica','direttore'],notificationsEnabled=userNotificationsEnabled(u.id),notificationControl=u.status==='pending'?'':`<button class="notification-toggle ${notificationsEnabled?'enabled':'disabled'}" data-notifications="${u.id}" data-next="${notificationsEnabled?'false':'true'}">${notificationsEnabled?'Notifiche attive':'Notifiche sospese'}</button>`,accessControl=u.status==='approved'?`<button class="user-access-button" data-user-access="${u.id}" data-user-access-name="${esc(u.display_name||u.email||'Utente')}" data-user-access-username="${esc(u.username||'')}">Gestisci accesso</button>`:'',teamControl=u.status==='approved'?`<button class="user-team-button" data-user-team="${u.id}" data-user-team-name="${esc(u.display_name||u.email||'Utente')}" data-team-code="${esc(u.team_code||'')}" data-team-color="${esc(u.team_color||'#168544')}">${u.team_code?`Squadra ${esc(u.team_code)}`:'Assegna squadra'}</button>`:'';return `<div class="user-row" data-user-search="${esc(search)}"><div><strong>${esc(u.display_name||'Senza nome')}</strong><small>@${esc(u.username||'—')} · ${esc(u.email)}</small></div><select data-role="${u.id}" ${u.role==='admin'?'disabled':''}>${roles.map(role=>`<option value="${role}" ${u.role===role?'selected':''}>${roleLabels[role]}</option>`).join('')}${u.role==='admin'?'<option value="admin" selected>Amministratore</option>':''}</select><span class="badge ${u.status}">${statusLabel[u.status]||u.status}</span>${teamControl}${accessControl}${notificationControl}${u.role==='admin'?'':`<button data-status="${u.id}" data-next="${u.status==='approved'?'blocked':'approved'}">${u.status==='approved'?'Rimuovi accesso':u.status==='blocked'?'Riattiva':'Approva'}</button>`}</div>`}
function filterUserArchive(value){const query=value.trim().toLowerCase();document.querySelectorAll('#userArchiveList .user-row').forEach(row=>row.hidden=!row.dataset.userSearch.includes(query));const visible=[...document.querySelectorAll('#userArchiveList .user-row')].filter(row=>!row.hidden).length;const count=$('#archiveResultCount');if(count)count.textContent=query?`${visible} risultati`:''}
function deviceArchiveHtml(devices,accesses,ready){if(!ready)return `<details class="user-archive device-archive"><summary><strong>Gestione dispositivi</strong></summary><div class="device-setup-notice"><strong>Registro pronto nell’app</strong><p>Per iniziare a raccogliere gli accessi occorre attivare le nuove tabelle nel database Supabase.</p></div></details>`;const statusLabel={pending:'In attesa',approved:'Autorizzato',blocked:'Bloccato'};return `<details class="user-archive device-archive"><summary><strong>Gestione dispositivi</strong> <span class="admin-count">${devices.length}</span></summary><p class="muted">Controlla quali account hanno utilizzato ogni dispositivo. Il registro identifica l’account di accesso: ogni persona deve usare soltanto le proprie credenziali.</p><div class="device-list">${devices.length?devices.map(device=>{const recent=accesses.filter(a=>a.device_id===device.id).slice(0,8),isCurrent=device.id===currentDeviceId();return `<article class="device-card ${device.status}"><div class="device-card-heading"><div><strong>${esc(device.label)}</strong><small>${esc(device.platform||'Dispositivo non identificato')}${isCurrent?' · Questo dispositivo':''}</small></div><span class="badge ${device.status}">${statusLabel[device.status]||device.status}</span></div><dl><div><dt>Ultimo utilizzatore</dt><dd>${esc(device.last_user_name||device.last_user_email||'—')}</dd></div><div><dt>Ultimo accesso</dt><dd>${showTime(device.last_seen)}</dd></div><div><dt>Codice</dt><dd>${esc(device.id.slice(0,8).toUpperCase())}</dd></div></dl><div class="device-actions"><button data-device-label="${device.id}" data-current-label="${esc(device.label)}">Rinomina</button><button class="${device.status==='approved'?'danger':'primary'}" data-device-status="${device.id}" data-next-device-status="${device.status==='approved'?'blocked':'approved'}">${device.status==='approved'?'Blocca dispositivo':'Autorizza dispositivo'}</button></div><details class="device-accesses"><summary>Accessi recenti (${recent.length})</summary>${recent.length?recent.map(access=>`<div><strong>${esc(access.user_name||access.user_email||'Utente')}</strong><small>Entrata ${showTime(access.signed_in_at)}${access.signed_out_at?` · Uscita ${showTime(access.signed_out_at)}`:' · Sessione non chiusa'}</small></div>`).join(''):'<p class="muted">Nessun accesso registrato.</p>'}</details></article>`}).join(''):'<p class="muted">Nessun dispositivo registrato. Comparirà dopo il primo accesso.</p>'}</div></details>`}
async function renderAdmin(){if(previewActive()||!isAdmin()||currentArea!=='production')return;let box=$('#adminPanel');if(!box){box=document.createElement('section');box.id='adminPanel';box.className='admin';document.body.insertBefore(box,$('#app'))}box.hidden=!adminManagementSection;const [profilesResult,devicesResult,accessResult]=await Promise.all([db.from('profiles').select('*').order('created_at',{ascending:false}),db.from('app_devices').select('*').order('last_seen',{ascending:false}),db.from('device_access_log').select('*').order('signed_in_at',{ascending:false}).limit(300)]);const {data,error}=profilesResult;if(previewActive()||error||currentArea!=='production'){box.hidden=true;return}const statusLabel={pending:'In attesa',approved:'Attivo',blocked:'Bloccato'},pending=data.filter(u=>u.status==='pending'),archived=data.filter(u=>u.status!=='pending'),devicesReady=!devicesResult.error&&!accessResult.error,devices=devicesResult.data||[],accesses=accessResult.data||[],desktopOpen=!matchMedia('(max-width:700px)').matches;adminPendingCount=pending.length;const menuBell=$('.admin-menu-bell'),menuRequestButton=document.querySelector('[data-admin-section="pending-users"]');if(menuBell){menuBell.hidden=!adminPendingCount;menuBell.setAttribute('aria-label',`${adminPendingCount} nuove richieste`);menuBell.querySelector('b').textContent=adminPendingCount}if(menuRequestButton)menuRequestButton.innerHTML=`Nuove richieste ${adminPendingCount?`<b class="admin-menu-inline-count">${adminPendingCount}</b>`:''}`;box.innerHTML=`<div class="admin-modal-top"><div class="admin-panel-heading"><h2>Amministratore</h2><details class="admin-info"><summary aria-label="Informazioni Amministratore">i</summary><p>Solo l’Amministratore può scegliere il ruolo, approvare, bloccare o modificare una persona. Negli archivi puoi gestire utenti, notifiche e dispositivi aziendali.</p></details></div><button id="closeAdminManagement" class="admin-modal-close">Chiudi ×</button></div><div class="admin-management-grid"><details class="pending-users" ${desktopOpen?'open':''}><summary><strong>Nuove richieste</strong> <span class="admin-count">${pending.length}</span></summary><div class="admin-section-content">${pending.length?pending.map(u=>adminUserRow(u,statusLabel)).join(''):'<p class="muted">Nessuna richiesta in attesa.</p>'}</div></details><details class="user-archive"><summary><strong>Archivio utenti</strong> <span class="admin-count">${archived.length}</span></summary><label class="field user-search">Cerca persona<input type="search" placeholder="Nome, username o e-mail" oninput="filterUserArchive(this.value)"></label><small id="archiveResultCount" class="muted"></small><div id="userArchiveList">${archived.map(u=>adminUserRow(u,statusLabel)).join('')}</div></details>${deviceArchiveHtml(devices,accesses,devicesReady)}</div>`;box.querySelectorAll('[data-role]').forEach(e=>e.onchange=()=>updateUser(e.dataset.role,{role:e.value}));box.querySelectorAll('[data-notifications]').forEach(e=>e.onclick=()=>setUserNotifications(e.dataset.notifications,e.dataset.next==='true'));box.querySelectorAll('[data-status]').forEach(e=>e.onclick=()=>updateUser(e.dataset.status,{status:e.dataset.next}));box.querySelectorAll('[data-device-status]').forEach(e=>e.onclick=()=>updateDevice(e.dataset.deviceStatus,{status:e.dataset.nextDeviceStatus}));box.querySelectorAll('[data-device-label]').forEach(e=>e.onclick=()=>renameDevice(e.dataset.deviceLabel,e.dataset.currentLabel));finishAdminPanel(box)}
function finishAdminPanel(box){box.querySelectorAll('[data-user-access]').forEach(button=>button.onclick=()=>showUserAccess(button.dataset.userAccess,button.dataset.userAccessName,button.dataset.userAccessUsername));box.querySelectorAll('[data-user-team]').forEach(button=>button.onclick=()=>showUserTeamAssignment(button));box.classList.toggle('admin-management-modal',!!adminManagementSection);const active=adminManagementSection?box.querySelector(`.${adminManagementSection}`):null;box.querySelectorAll('.admin-management-grid>details').forEach(item=>item.open=item===active);const summary=active?.querySelector('summary');if(summary)summary.onclick=e=>e.preventDefault();const close=$('#closeAdminManagement');if(close)close.onclick=closeAdminManagement;box.hidden=!adminManagementSection}
function showUserTeamAssignment(button){if(!actualIsAdmin())return;const id=button.dataset.userTeam,name=button.dataset.userTeamName,dialog=bottleEditorShell(`<strong class="bottle-editor-title">Squadra di ${esc(name)}</strong><p>Questa scelta determina quale conversazione la persona può vedere dopo il login.</p><label class="field">Nome o codice squadra<input id="userTeamCode" maxlength="40" value="${esc(button.dataset.teamCode||'')}" placeholder="Esempio: Verde"></label><label class="field">Colore squadra<input id="userTeamColor" type="color" value="${safeTeamColor(button.dataset.teamColor)}"></label><div class="line-quick-actions"><button type="button" class="primary" id="saveUserTeam">Salva squadra</button><button type="button" id="removeUserTeam">Rimuovi assegnazione</button></div>`);dialog.querySelector('#saveUserTeam').onclick=async()=>{const team_code=dialog.querySelector('#userTeamCode').value.trim(),team_color=dialog.querySelector('#userTeamColor').value;if(!team_code)return toast('Inserisci il nome della squadra',true);const {error}=await db.from('profiles').update({team_code,team_color}).eq('id',id);if(error)return toast(error.message,true);dialog.close();renderAdmin();toast('Squadra assegnata')};dialog.querySelector('#removeUserTeam').onclick=async()=>{const {error}=await db.from('profiles').update({team_code:null,team_color:null}).eq('id',id);if(error)return toast(error.message,true);dialog.close();renderAdmin();toast('Assegnazione squadra rimossa')}}
async function updateDevice(id,{status=null,label=null}={}){if(previewActive()||!actualIsAdmin())return toast('Solo l’Amministratore può gestire i dispositivi',true);const {error}=await db.rpc('admin_update_device',{p_device_id:id,p_status:status,p_label:label});if(error)return toast(error.message||'Dispositivo non aggiornato',true);toast(status==='blocked'?'Dispositivo bloccato':'Dispositivo aggiornato');renderAdmin()}
function renameDevice(id,currentLabel){const label=prompt('Nome riconoscibile del dispositivo',currentLabel||'');if(label?.trim())updateDevice(id,{label:label.trim()})}
async function setUserNotifications(id,enabled){if(previewActive())return toast('Gestione utenti bloccata durante l’anteprima',true);if(!actualIsAdmin())return toast('Solo l’Amministratore può modificare gli utenti',true);appState.notificationUsers[id]=enabled;await save();toast(enabled?'Notifiche riattivate':'Notifiche sospese');renderAdmin()}
async function updateUser(id,change){if(previewActive())return toast('Gestione utenti bloccata durante l’anteprima',true);if(!actualIsAdmin())return toast('Solo l’Amministratore può modificare o approvare un utente',true);const {error}=await db.from('profiles').update(change).eq('id',id);if(error)return toast(error.message,true);toast('Utente aggiornato');renderAdmin()}
const shiftCodeInfo={1:{label:'Turno 1',className:'one'},2:{label:'Turno 2',className:'two'},3:{label:'Turno 3',className:'three'},R:{label:'Riposo',className:'rest'},F:{label:'Ferie',className:'holiday'},C:{label:'Centrale',className:'central'},MC:{label:'MC',className:'mc'}};
function shiftDateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function shiftDateLabel(date,options={}){return date.toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short',...options})}
function shiftWeekDays(){const date=new Date(),day=(date.getDay()+6)%7;date.setHours(12,0,0,0);date.setDate(date.getDate()-day+(shiftWeekOffset*7));return Array.from({length:7},(_,index)=>{const item=new Date(date);item.setDate(date.getDate()+index);return item})}
function shiftAssignment(personId,date){return appState.shifts.assignments[`${personId}|${shiftDateKey(date)}`]||''}
function shiftBadge(code){const info=shiftCodeInfo[code]||{label:code||'Non assegnato',className:'empty'};return `<span class="shift-badge shift-${info.className}"><b>${esc(code||'—')}</b><small>${esc(info.label)}</small></span>`}
function shiftWeekCards(people,days,editable){if(!people.length)return '<div class="shift-empty"><strong>Nessuna persona trovata</strong><p>Aggiungi una persona oppure modifica la ricerca.</p></div>';return `<div class="shift-people-list">${people.map(person=>`<article class="shift-person-card" data-shift-search="${esc(`${person.name} ${person.jobTitle||''}`.toLowerCase())}"><div class="shift-person-heading"><div><strong>${esc(person.name)}</strong><small>${esc(person.jobTitle||'Mansione non indicata')}</small></div>${editable?`<button class="shift-person-edit" data-edit-shift-person="${person.id}" aria-label="Modifica ${esc(person.name)}">✎</button>`:''}</div><div class="shift-week-row">${days.map(date=>{const code=shiftAssignment(person.id,date),info=shiftCodeInfo[code]||{className:'empty'};return `<button class="shift-day shift-${info.className}" data-shift-person="${person.id}" data-shift-date="${shiftDateKey(date)}" ${editable?'':'disabled'}><small>${shiftDateLabel(date)}</small><b>${esc(code||'—')}</b></button>`}).join('')}</div></article>`).join('')}</div>`}
function renderShiftsHub(){const hub=$('#shiftsApp'),editable=canManageShifts(),people=[...appState.shifts.people].sort((a,b)=>(a.name||'').localeCompare(b.name||'','it')),today=new Date(),todayKey=shiftDateKey(today),days=shiftWeekDays(),weekTitle=`${shiftDateLabel(days[0],{weekday:undefined})} - ${shiftDateLabel(days[6],{weekday:undefined})}`;let content='';if(shiftView==='today'){const groups=['1','2','3','C','R','F','MC',''];content=`<section class="shift-today"><div class="shift-section-title"><div><span class="area-eyebrow">${shiftDateLabel(today)}</span><h2>Turni di oggi</h2></div></div><div class="shift-today-grid">${groups.map(code=>{const members=people.filter(person=>(appState.shifts.assignments[`${person.id}|${todayKey}`]||'')===code);if(!members.length&&code)return'';return `<article class="shift-today-group ${code?'':'unassigned'}"><header>${shiftBadge(code)}<strong>${members.length} ${members.length===1?'persona':'persone'}</strong></header>${members.length?members.map(person=>`<button ${editable?`data-shift-person="${person.id}" data-shift-date="${todayKey}"`:''}><span>${esc(person.name)}</span><small>${esc(person.jobTitle||'')}</small></button>`).join(''):'<p>Nessuna persona ancora inserita.</p>'}</article>`}).join('')}</div></section>`}else{const shown=shiftView==='search'?people.filter(person=>`${person.name} ${person.jobTitle||''}`.toLowerCase().includes(shiftSearch.toLowerCase())):people;content=`<section class="shift-week"><div class="shift-week-toolbar"><button id="shiftPrevWeek" aria-label="Settimana precedente">‹</button><strong>${esc(weekTitle)}</strong><button id="shiftCurrentWeek">Oggi</button><button id="shiftNextWeek" aria-label="Settimana successiva">›</button></div>${shiftView==='search'?`<label class="field shift-search">Cerca persona<input id="shiftSearchInput" type="search" value="${esc(shiftSearch)}" placeholder="Nome o mansione"></label>`:''}${shiftWeekCards(shown,days,editable)}</section>`}hub.innerHTML=`<div class="area-topbar shifts-topbar"><button id="shiftsBack">← Scelta aree</button><span>Turni</span>${editable?'<button class="primary" id="addShiftPerson">＋ Aggiungi persona</button>':''}</div><section class="shift-hero"><div><span class="area-eyebrow">Programmazione semplificata</span><h1>Turni</h1><p>Consulta rapidamente oggi, la settimana o cerca una persona.</p></div>${editable?'<span class="shift-manager-badge">Puoi modificare</span>':'<span class="shift-viewer-badge">Solo consultazione</span>'}</section><nav class="shift-tabs" aria-label="Viste turni"><button data-shift-view="today" ${shiftView==='today'?'class="selected"':''}>Oggi</button><button data-shift-view="week" ${shiftView==='week'?'class="selected"':''}>Settimana</button><button data-shift-view="search" ${shiftView==='search'?'class="selected"':''}>Cerca persona</button></nav><div class="shift-legend">${Object.entries(shiftCodeInfo).map(([code])=>shiftBadge(code)).join('')}</div>${!people.length&&editable?'<div class="notice shift-start-notice"><strong>Inizia la programmazione</strong><p>Aggiungi la prima persona e poi assegna i turni toccando le caselle dei giorni.</p></div>':''}${content}`;$('#shiftsBack').onclick=()=>openArea('home');if($('#addShiftPerson'))$('#addShiftPerson').onclick=()=>showShiftPersonDialog();hub.querySelectorAll('[data-shift-view]').forEach(button=>button.onclick=()=>{shiftView=button.dataset.shiftView;renderShiftsHub()});hub.querySelectorAll('[data-shift-person]').forEach(button=>button.onclick=()=>showShiftEditor(button.dataset.shiftPerson,button.dataset.shiftDate));hub.querySelectorAll('[data-edit-shift-person]').forEach(button=>button.onclick=()=>showShiftPersonDialog(button.dataset.editShiftPerson));if($('#shiftPrevWeek'))$('#shiftPrevWeek').onclick=()=>{shiftWeekOffset--;renderShiftsHub()};if($('#shiftNextWeek'))$('#shiftNextWeek').onclick=()=>{shiftWeekOffset++;renderShiftsHub()};if($('#shiftCurrentWeek'))$('#shiftCurrentWeek').onclick=()=>{shiftWeekOffset=0;renderShiftsHub()};if($('#shiftSearchInput'))$('#shiftSearchInput').oninput=e=>filterShiftPeople(e.target.value)}
function filterShiftPeople(value){shiftSearch=value;const query=value.trim().toLowerCase();document.querySelectorAll('.shift-person-card').forEach(card=>card.hidden=!card.dataset.shiftSearch.includes(query))}
function showShiftPersonDialog(personId=''){if(!canManageShifts())return toast('Solo Amministratore e Direttore possono modificare i turni',true);const person=appState.shifts.people.find(item=>item.id===personId),dialog=bottleEditorShell(`<strong class="bottle-editor-title">${person?'Modifica persona':'Aggiungi persona'}</strong><p>Inserisci i dati usati nel prospetto turni.</p><label class="field">Nome e cognome<input id="shiftPersonName" value="${esc(person?.name||'')}" autocomplete="off"></label><label class="field">Mansione o gruppo<input id="shiftPersonJob" value="${esc(person?.jobTitle||'')}" placeholder="Esempio: Operatore, CT, Logistica"></label><div class="line-quick-actions"><button class="primary" id="saveShiftPerson">Salva</button>${person?'<button class="danger" id="removeShiftPerson">Rimuovi persona</button>':''}</div>`);dialog.querySelector('#saveShiftPerson').onclick=async()=>{const name=$('#shiftPersonName').value.trim(),jobTitle=$('#shiftPersonJob').value.trim();if(!name)return toast('Inserisci nome e cognome',true);if(person){person.name=name;person.jobTitle=jobTitle}else appState.shifts.people.push({id:crypto.randomUUID(),name,jobTitle});await save();dialog.close();renderShiftsHub();toast(person?'Persona aggiornata':'Persona aggiunta')};if(person)dialog.querySelector('#removeShiftPerson').onclick=async()=>{if(!confirm(`Rimuovere ${person.name} dal prospetto turni?`))return;appState.shifts.people=appState.shifts.people.filter(item=>item.id!==person.id);Object.keys(appState.shifts.assignments).filter(key=>key.startsWith(`${person.id}|`)).forEach(key=>delete appState.shifts.assignments[key]);await save();dialog.close();renderShiftsHub();toast('Persona rimossa')}}
function showShiftEditor(personId,dateKey){if(!canManageShifts())return;const person=appState.shifts.people.find(item=>item.id===personId);if(!person)return;const current=appState.shifts.assignments[`${personId}|${dateKey}`]||'',dialog=bottleEditorShell(`<strong class="bottle-editor-title">Turno di ${esc(person.name)}</strong><label class="field">Giorno<input id="shiftEditDate" type="date" value="${esc(dateKey)}"></label><label class="field">Turno o stato<select id="shiftEditCode"><option value="">Nessuna assegnazione</option>${Object.entries(shiftCodeInfo).map(([code,info])=>`<option value="${code}" ${current===code?'selected':''}>${code} - ${esc(info.label)}</option>`).join('')}</select></label><div class="line-quick-actions"><button class="primary" id="saveShiftAssignment">Salva turno</button></div>`);dialog.querySelector('#saveShiftAssignment').onclick=async()=>{const newDate=$('#shiftEditDate').value,code=$('#shiftEditCode').value;if(!newDate)return toast('Scegli il giorno',true);if(newDate!==dateKey)delete appState.shifts.assignments[`${personId}|${dateKey}`];const key=`${personId}|${newDate}`;if(code)appState.shifts.assignments[key]=code;else delete appState.shifts.assignments[key];await save();dialog.close();renderShiftsHub();toast('Turno aggiornato')}}
async function boot(){if(DEMO_MODE){profile={display_name:'CT Demo',role:'ct',status:'approved'};render();await loadRemote();return}const {data}=await db.auth.getSession();session=data.session;if(session){try{profile=await getProfile()}catch(e){toast('Profilo non disponibile',true)}}if(IS_RECOVERY&&session)accessScreen();else if(profile?.status==='approved')await enterApprovedSession();else accessScreen();db.auth.onAuthStateChange(async(event,s)=>{session=s;if(s){profile=await getProfile();if(event==='PASSWORD_RECOVERY')accessScreen();else if(profile.status==='approved')await enterApprovedSession();else accessScreen()}else accessScreen()})}
document.addEventListener('pointerdown',event=>{const menu=document.querySelector('.admin-header-menu[open]');if(menu&&!menu.contains(event.target)){menu.open=false;document.body.classList.remove('admin-header-menu-open')}});
window.addEventListener('resize',()=>positionAdminHeaderMenu());
preventAppZoom();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});boot();setInterval(()=>{updatePriorityTimers();updateShiftCountdown()},1000);setInterval(async()=>{if(session){try{const p=await getProfile();if(p.status!==profile?.status||p.role!==profile?.role){profile=p;await loadOperators();render()}}catch{}}loadRemote()},2500);
